WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM payments), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN amount >= 1370 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, DATE_TRUNC('QUARTER', paid_at) AS quarter_start, MAX(island_id) AS max_island_id, COUNT(*) FILTER (WHERE status = 'SUCCESS') AS success_rows, MIN(paid_at) AS first_seen, PERCENTILE_APPROX(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS failed_count, SUM(CASE WHEN status = 'SUCCESS' THEN is_new_burst ELSE 0 END) AS success_is_new_burst FROM islands GROUP BY CASE WHEN amount >= 1370 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('QUARTER', paid_at);
